parameters.jsCode:
const text = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '{"selections":[]}';
try {
  const parsed = JSON.parse(text);
  return [{ json: { selections: Array.isArray(parsed.selections) ? parsed.selections : [] } }];
} catch {
  return [{ json: { selections: [] } }];
}
